def parse_turtle(text):
    tokens = []
    for line in text.splitlines():
        line = line.strip()
        if line and not line.startswith("#"):
            tokens += line.split()

    triples = set()
    subject = predicate = None
    expect = "subject"
    for token in tokens:
        if token == ".":
            subject = predicate = None
            expect = "subject"
        elif token == ";":
            expect = "predicate"
        elif token == ",":
            expect = "object"
        elif expect == "subject":
            subject, expect = token, "predicate"
        elif expect == "predicate":
            predicate = "rdf:type" if token == "a" else token
            expect = "object"
        else:
            triples.add((subject, predicate, token))
    return triples
